<script>
  // `size`: quanti pixel di schermo per pixel dello sprite; `fit`: il lato più lungo, in pixel (per il negozio).
  let { id, size = 3, fit = 0 } = $props();
  const art = $derived(ART[id]);
  const k = $derived(fit ? fit / Math.max(art[0], art[1]) : size);
